  ('P3','ENG','ENG-T2','ENG-T2-O2','Choose the correct pronoun: ''Emeka plays football. ___ is happy.''','[{"id": "a", "text": "She"}, {"id": "b", "text": "He"}, {"id": "c", "text": "It"}, {"id": "d", "text": "We"}]','{"correct": ["b"], "explanation": "''He'' replaces a male person like Emeka."}',0.25,'{P3,ENG,nerdc-quiz-seed-v1}'),
  ('P3','ENG','ENG-T2','ENG-T2-O2','Choose the correct pronoun: ''The book is new. ___ is on the table.''','[{"id": "a", "text": "He"}, {"id": "b", "text": "She"}, {"id": "c", "text": "It"}, {"id": "d", "text": "They"}]','{"correct": ["c"], "explanation": "''It'' replaces one thing like a book."}',0.25,'{P3,ENG,nerdc-quiz-seed-v1}'),
